    "title": "Two audit dimensions need separate checks",
    "description": "Two audit dimensions need separate checks",
    "audience": "Reviewers",
    "rationale": "Preserve observed conclusions and their limits.",
    "evidence": "Wrong dates prove shelf-order failure."
  }
